using System;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using TMPro;
using Unity.Netcode;
using Unity.Netcode.Transports.UTP;
using UnityEditor;
using UnityEditor.Events;
using UnityEditor.SceneManagement;

public static class CreateRoomSceneSetup
{
    public static string Run()
    {
        var networkManager = UnityEngine.Object.FindFirstObjectByType<NetworkManager>();
        if (networkManager == null)
        {
            var networkGo = new GameObject("NetworkManager");
            networkManager = networkGo.AddComponent<NetworkManager>();
            networkGo.AddComponent<UnityTransport>();
        }

        var transport = networkManager.GetComponent<UnityTransport>();
        if (transport == null)
        {
            transport = networkManager.gameObject.AddComponent<UnityTransport>();
        }

        transport.SetRelayServerData(default);
        networkManager.NetworkConfig.NetworkTransport = transport;
        networkManager.RunInBackground = true;

        var existingService = UnityEngine.Object.FindFirstObjectByType<MultiplayerRoomService>();
        MultiplayerRoomService roomService;
        if (existingService == null)
        {
            var serviceGo = new GameObject("MultiplayerRoomService");
            roomService = serviceGo.AddComponent<MultiplayerRoomService>();
        }
        else
        {
            roomService = existingService;
        }

        var serviceSo = new SerializedObject(roomService);
        serviceSo.FindProperty("maxPlayers").intValue = 4;
        serviceSo.FindProperty("gameplaySceneName").stringValue = "Gameplay";
        serviceSo.FindProperty("loadGameplaySceneOnConnect").boolValue = false;
        serviceSo.ApplyModifiedPropertiesWithoutUndo();

        if (UnityEngine.Object.FindFirstObjectByType<EventSystem>() == null)
        {
            var eventSystemGo = new GameObject("EventSystem");
            eventSystemGo.AddComponent<EventSystem>();
            eventSystemGo.AddComponent<StandaloneInputModule>();
        }

        var existingUi = UnityEngine.Object.FindFirstObjectByType<MultiplayerRoomUI>();
        if (existingUi != null)
        {
            UnityEngine.Object.DestroyImmediate(existingUi.transform.root.gameObject.name == "RoomCanvas" ? existingUi.transform.root.gameObject : existingUi.gameObject);
        }

        var canvasGo = new GameObject("RoomCanvas");
        var canvas = canvasGo.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.ScreenSpaceOverlay;
        var scaler = canvasGo.AddComponent<CanvasScaler>();
        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
        scaler.referenceResolution = new Vector2(1920, 1080);
        canvasGo.AddComponent<GraphicRaycaster>();

        var uiRoot = new GameObject("RoomUI");
        uiRoot.transform.SetParent(canvasGo.transform, false);
        var uiRect = uiRoot.AddComponent<RectTransform>();
        Stretch(uiRect);
        var roomUi = uiRoot.AddComponent<MultiplayerRoomUI>();

        var background = CreatePanel(uiRoot.transform, "Background", new Color(0.08f, 0.1f, 0.14f, 0.95f));
        Stretch(background.GetComponent<RectTransform>());

        var mainPanel = CreatePanel(uiRoot.transform, "MainPanel", new Color(0.12f, 0.15f, 0.2f, 0.98f));
        SetupCenterPanel(mainPanel.GetComponent<RectTransform>(), 700, 500);

        var hostPanel = CreatePanel(uiRoot.transform, "HostPanel", new Color(0.12f, 0.15f, 0.2f, 0.98f));
        SetupCenterPanel(hostPanel.GetComponent<RectTransform>(), 700, 500);
        hostPanel.SetActive(false);

        var joinPanel = CreatePanel(uiRoot.transform, "JoinPanel", new Color(0.12f, 0.15f, 0.2f, 0.98f));
        SetupCenterPanel(joinPanel.GetComponent<RectTransform>(), 700, 500);
        joinPanel.SetActive(false);

        var title = CreateText(mainPanel.transform, "TitleText", "Create Room", 54, FontStyles.Bold);
        SetAnchored(title.rectTransform, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0, -60));
        title.alignment = TextAlignmentOptions.Center;

        var statusText = CreateText(mainPanel.transform, "StatusText", "Ready for multiplayer", 28, FontStyles.Normal);
        SetAnchored(statusText.rectTransform, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0, 40));
        statusText.alignment = TextAlignmentOptions.Center;
        statusText.color = new Color(0.8f, 0.85f, 0.9f);

        var hostButton = CreateButton(mainPanel.transform, "HostButton", "HOST", new Vector2(0, 40));
        var joinButton = CreateButton(mainPanel.transform, "JoinButton", "JOIN", new Vector2(0, -80));

        var hostTitle = CreateText(hostPanel.transform, "HostTitle", "Your Room Code", 42, FontStyles.Bold);
        SetAnchored(hostTitle.rectTransform, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0, -70));
        hostTitle.alignment = TextAlignmentOptions.Center;

        var hostRoomCodeText = CreateText(hostPanel.transform, "HostRoomCodeText", "------", 72, FontStyles.Bold);
        SetAnchored(hostRoomCodeText.rectTransform, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(0, 40));
        hostRoomCodeText.alignment = TextAlignmentOptions.Center;
        hostRoomCodeText.color = new Color(1f, 0.84f, 0.2f);

        CreateText(hostPanel.transform, "HostStatusText", "Share this code with friends", 26, FontStyles.Normal);
        var hostBackButton = CreateButton(hostPanel.transform, "HostBackButton", "BACK", new Vector2(0, -120));
        var leaveButton = CreateButton(hostPanel.transform, "LeaveButton", "LEAVE", new Vector2(0, -200));
        leaveButton.gameObject.SetActive(false);

        var joinTitle = CreateText(joinPanel.transform, "JoinTitle", "Enter Room Code", 42, FontStyles.Bold);
        SetAnchored(joinTitle.rectTransform, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0, -70));
        joinTitle.alignment = TextAlignmentOptions.Center;

        var joinInput = CreateInputField(joinPanel.transform, "JoinCodeInput");
        SetAnchored(joinInput.GetComponent<RectTransform>(), new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(0, 20));

        var confirmJoinButton = CreateButton(joinPanel.transform, "ConfirmJoinButton", "JOIN ROOM", new Vector2(0, -100));
        var joinBackButton = CreateButton(joinPanel.transform, "JoinBackButton", "BACK", new Vector2(0, -180));

        WireButton(hostButton, roomUi, nameof(MultiplayerRoomUI.OnClickHost));
        WireButton(joinButton, roomUi, nameof(MultiplayerRoomUI.OnClickJoin));
        WireButton(confirmJoinButton, roomUi, nameof(MultiplayerRoomUI.OnClickConfirmJoin));
        WireButton(leaveButton, roomUi, nameof(MultiplayerRoomUI.OnClickLeave));
        WireButton(hostBackButton, roomUi, nameof(MultiplayerRoomUI.OnClickBack));
        WireButton(joinBackButton, roomUi, nameof(MultiplayerRoomUI.OnClickBack));

        var uiSo = new SerializedObject(roomUi);
        uiSo.FindProperty("mainPanel").objectReferenceValue = mainPanel;
        uiSo.FindProperty("hostPanel").objectReferenceValue = hostPanel;
        uiSo.FindProperty("joinPanel").objectReferenceValue = joinPanel;
        uiSo.FindProperty("hostRoomCodeText").objectReferenceValue = hostRoomCodeText;
        uiSo.FindProperty("statusText").objectReferenceValue = statusText;
        uiSo.FindProperty("joinCodeInput").objectReferenceValue = joinInput;
        uiSo.FindProperty("joinButton").objectReferenceValue = joinButton;
        uiSo.FindProperty("hostButton").objectReferenceValue = hostButton;
        uiSo.FindProperty("leaveButton").objectReferenceValue = leaveButton;
        uiSo.ApplyModifiedPropertiesWithoutUndo();

        EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());
        return "CreateRoom scene setup complete";
    }

    private static GameObject CreatePanel(Transform parent, string name, Color color)
    {
        var go = new GameObject(name);
        go.transform.SetParent(parent, false);
        go.AddComponent<Image>().color = color;
        return go;
    }

    private static void Stretch(RectTransform rect)
    {
        rect.anchorMin = Vector2.zero;
        rect.anchorMax = Vector2.one;
        rect.offsetMin = Vector2.zero;
        rect.offsetMax = Vector2.zero;
    }

    private static void SetupCenterPanel(RectTransform rect, float width, float height)
    {
        rect.anchorMin = new Vector2(0.5f, 0.5f);
        rect.anchorMax = new Vector2(0.5f, 0.5f);
        rect.sizeDelta = new Vector2(width, height);
        rect.anchoredPosition = Vector2.zero;
    }

    private static void SetAnchored(RectTransform rect, Vector2 anchorMin, Vector2 anchorMax, Vector2 anchoredPosition)
    {
        rect.anchorMin = anchorMin;
        rect.anchorMax = anchorMax;
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.sizeDelta = new Vector2(500, 80);
        rect.anchoredPosition = anchoredPosition;
    }

    private static TMP_Text CreateText(Transform parent, string name, string text, float fontSize, FontStyles style)
    {
        var go = new GameObject(name);
        go.transform.SetParent(parent, false);
        var tmp = go.AddComponent<TextMeshProUGUI>();
        tmp.text = text;
        tmp.fontSize = fontSize;
        tmp.fontStyle = style;
        tmp.color = Color.white;
        return tmp;
    }

    private static Button CreateButton(Transform parent, string name, string label, Vector2 anchoredPosition)
    {
        var go = new GameObject(name);
        go.transform.SetParent(parent, false);
        go.AddComponent<Image>().color = new Color(0.2f, 0.55f, 0.95f, 1f);
        var button = go.AddComponent<Button>();
        var rect = go.GetComponent<RectTransform>();
        rect.sizeDelta = new Vector2(320, 64);
        rect.anchoredPosition = anchoredPosition;
        var text = CreateText(go.transform, "Text", label, 28, FontStyles.Bold);
        Stretch(text.rectTransform);
        text.alignment = TextAlignmentOptions.Center;
        return button;
    }

    private static TMP_InputField CreateInputField(Transform parent, string name)
    {
        var go = new GameObject(name);
        go.transform.SetParent(parent, false);
        go.AddComponent<Image>().color = new Color(0.05f, 0.07f, 0.1f, 1f);
        var input = go.AddComponent<TMP_InputField>();
        go.GetComponent<RectTransform>().sizeDelta = new Vector2(420, 70);

        var textGo = new GameObject("Text");
        textGo.transform.SetParent(go.transform, false);
        var text = textGo.AddComponent<TextMeshProUGUI>();
        text.fontSize = 36;
        text.alignment = TextAlignmentOptions.Center;
        text.color = Color.white;
        Stretch(text.GetComponent<RectTransform>());

        var placeholderGo = new GameObject("Placeholder");
        placeholderGo.transform.SetParent(go.transform, false);
        var placeholder = placeholderGo.AddComponent<TextMeshProUGUI>();
        placeholder.text = "ABC123";
        placeholder.fontSize = 28;
        placeholder.fontStyle = FontStyles.Italic;
        placeholder.color = new Color(1f, 1f, 1f, 0.35f);
        placeholder.alignment = TextAlignmentOptions.Center;
        Stretch(placeholder.GetComponent<RectTransform>());

        input.textComponent = text;
        input.placeholder = placeholder;
        input.characterLimit = 6;
        input.contentType = TMP_InputField.ContentType.Alphanumeric;
        return input;
    }

    private static void WireButton(Button button, MultiplayerRoomUI target, string methodName)
    {
        while (button.onClick.GetPersistentEventCount() > 0)
        {
            UnityEventTools.RemovePersistentListener(button.onClick, 0);
        }

        var method = typeof(MultiplayerRoomUI).GetMethod(methodName);
        if (method != null)
        {
            UnityEventTools.AddPersistentListener(button.onClick, (UnityEngine.Events.UnityAction)Delegate.CreateDelegate(typeof(UnityEngine.Events.UnityAction), target, method));
        }
    }
}
